import{_ as l,l as n,o as e,c as i,v as t,p as s,x as o,d as E,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"斯塔克尔伯格与领导者","description":"","frontmatter":{"title":"斯塔克尔伯格与领导者","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/stackelberg.md","filePath":"econ/stackelberg.md","lastUpdated":1789023840000}'),_={name:"econ/stackelberg.md"};function d(h,a,A,B,m,q){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="斯塔克尔伯格与领导者" tabindex="-1">斯塔克尔伯格与领导者 <a class="header-anchor" href="#斯塔克尔伯格与领导者" aria-label="Permalink to &quot;斯塔克尔伯格与领导者&quot;">​</a></h1><div class="epigraph"><p>若一家能在对方之前把产量写进可观察的承诺，它会把跟随者的反应函数当作约束，而不是当作同时的猜测。</p><footer>—— 据 von Stackelberg, Marktform und Gleichgewicht, 1934 整理</footer></div><p><a href="/econ/collusion-cartel">上一课</a>（合谋与卡特尔）。表明：同时选价格可以落到 MC，同时选产能可以回到古诺。本课不重讲配给规则。缺口是：两阶段里产能仍是<strong>同时</strong>选的。若一家能先把数量（或产能）钉死、并让对方看见，跟随者的问题变成古诺里的单侧反应，领导者在反应曲线上选最利点。同时均衡与先动均衡不是同一个点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>跟随者 \\(F\\) 在看见 \\(q_L\\) 之后解 \\(\\max_{q_F} P(q_L+q_F)q_F-c_F(q_F)\\)，得到 \\(q_F=R(q_L)\\)——这正是<a href="/econ/cournot-oligopoly">古诺</a>的一条反应函数，但现在它是真实的后手，不是互相猜测。领导者解</p> \\[\\max_{q_L}\\, P\\bigl(q_L+R(q_L)\\bigr)q_L-c_L(q_L). \\]<p>一阶条件多出一项 \\(P&#39;\\cdot R&#39;(q_L)\\cdot q_L\\)：领导者内化「我多产一单位，对方会减产」。通常 \\(R&#39;\\lt 0\\)，这一项为正，领导者比古诺产得更多，跟随者更少，总产量更高、价格更低，领导者利润高于古诺，跟随者低于古诺。缺口不是再画一次 MR，而是：<strong>可观察的先动把反应从猜测变成约束</strong>。</p><p>承诺必须不可撤销。口头「我会产很多」若能在对方行动前改口，博弈缩回同时选择。产能、合同、沉没投资是承诺的物质形式，上一课序的沉没在这里变成策略工具。</p><h3 id="先动优势不是先喊价优势" tabindex="-1">先动优势不是先喊价优势 <a class="header-anchor" href="#先动优势不是先喊价优势" aria-label="Permalink to &quot;先动优势不是先喊价优势&quot;">​</a></h3><p>数量上的领导常常有利。价格上的领导在同质产品里往往不利：先贴出的价被后手底切，回到伯川德逻辑。故「领导者」必须声明策略变量。本课钉产量（产能）领导，与古诺、与 Kreps–Scheinkman 的同时产能对照。不要把零售里的「价格领导」未经翻译写成斯塔克尔伯格。</p><p><span class="marginnote">逆向归纳：先写跟随者的最优，再代回领导者。这与后课子博弈完美是同一算法，本课只在双寡头产量上用一次，不展开扩展式的一般定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>几何：在跟随者的反应曲线上，找领导者等利润线的切点。切点一般不在古诺交点——古诺交点是两条反应曲线的交，领导者并不站在自己那条同时反应上，因为他不把对方的产量当给定，而把对方的<strong>规则</strong>当给定。比较静态：领导者成本下降，自己产量升得比古诺更猛，因为还要多挤占跟随者。</p><p>若两家都能抢先，会出现「谁当领导」的元博弈；双方都想当数量领导时，可能过度扩张。本课把领导身份当给定，以免滑进同时选时机的复杂均衡。</p>',14)),(e(),s(p,null,{default:o(()=>[c(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIM%5B%22%E5%90%8C%E6%97%B6%EF%BC%9A%E5%8F%A4%E8%AF%BA%E6%88%96%E5%90%8C%E6%97%B6%E4%BA%A7%E8%83%BD%22%5D%20--%3E%20SEQ%5B%22q_L%20%E5%85%88%E9%92%89%E6%AD%BB%E4%B8%94%E5%8F%AF%E8%A7%82%E5%AF%9F%22%5D%0A%20%20SEQ%20--%3E%20R%5B%22%E8%B7%9F%E9%9A%8F%E8%80%85%E6%B2%BF%20R(q_L)%22%5D%0A%20%20R%20--%3E%20LEAD%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%E5%9C%A8%20R%20%E4%B8%8A%E9%80%89%E5%88%87%E7%82%B9%22%5D%0A%20%20LEAD%20--%3E%20ADV%5B%22%E5%85%88%E5%8A%A8%EF%BC%9A%E9%87%8F%E6%9B%B4%E5%A4%A7%E3%80%81%E5%88%A9%E6%B6%A6%E6%9B%B4%E9%AB%98%22%5D%0A%20%20ADV%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%BA%A7%E5%93%81%E4%B8%8D%E5%86%8D%E5%90%8C%E8%B4%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>线性常 MC 教具上，领导者产量等于垄断产量，但市场总量大于垄断、也大于古诺，价格介于二者之间。追随者利润低于古诺。没有可观察、不可逆的承诺，先走没有用，退回同时行动。</p><p>产品仍同质。差异化之后，反应函数的斜率会变，先动的符号也可能变；那是下一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内化反应的机制是链式法则：领导者的边际收入比古诺多出「对方让出的数量」。策略替代（\\(R&#39;\\lt 0\\)）时，多产是进攻，把跟随者挤到更陡的剩余需求上。若策略互补，先动逻辑会翻转——差异产品价格竞争里常见，本课不同质数量下通常遇不到。</p><p>承诺的机制是沉没：先建的工厂改变后手面对的剩余需求，后手再优化时已经晚了。没有沉没、没有合同、没有公开的产能，斯塔克尔伯格点不可实施，观测上应回到古诺或伯川德。故本课与<a href="/econ/sunk-cost">短长期</a>是同一把刀：沉没从「不影响本期歇业」变成「能改别人的反应」。</p><p><span class="marginnote">von Stackelberg 1934 的原书用德文讨论市场形式。现代教科书的反应曲线图是后人对数量领导的标准写法。不要把这篇写成 1980 年代的产业组织综述。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>信息不完全时，先动可能变成信号而不是单纯承诺，那是信号课。多跟随者、连续时间抢先，会改先动优势的分配。卡特尔里指定一家领导，是合谋安排，不是本课的非合作先动。</p><p>也不要把限价簿上的先行委托单写成斯塔克尔伯格：时间优先是微观结构，对手不必沿一条光滑 \\(R(q)\\) 反应。</p><p>后课默认：可观察的产量承诺给出斯塔克尔伯格点；同时选择仍读古诺。下一课撤掉同质，让位置本身成为策略。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跟随者走古诺反应；领导者在这条约束上选产量，内化 \\(R&#39;\\)。</li><li>数量领导通常产得更多、利润更高；承诺必须不可撤销。</li><li>价格领导与数量领导符号可以相反，必须声明策略变量。</li><li>下一课用线性城市把产品差异做成位置与价格。</li><li>出处：von Stackelberg, <em>Marktform und Gleichgewicht</em>, 1934；Cournot, 1838；Mas-Colell, Whinston and Green 第 12 章。</li></ul>',12))])}const b=l(_,[["render",d]]);export{f as __pageData,b as default};
